function validate([n, edges, threshold]) {
  if (n < 2 || n > 100000) return 'n is between 2 and 10^5.';
  if (threshold < 1 || threshold > n - 1) return 'threshold is between 1 and n - 1.';
  if (edges.length < 1 || edges.length > Math.min(100000, n * (n - 1) / 2)) return 'edges needs between 1 and min(10^5, n * (n - 1) / 2) entries.';
  const seen = new Set();
  for (const edge of edges) {
    if (edge.length !== 3) return 'Each edge is [A, B, W].';
    const [a, b, w] = edge;
    if (a < 0 || a >= n || b < 0 || b >= n) return 'Edge endpoints are nodes 0 to n - 1.';
    if (a === b) return 'An edge cannot start and end at the same node.';
    if (w < 1 || w > 1000000) return 'Each weight is between 1 and 10^6.';
    const key = Math.min(a, b) + ',' + Math.max(a, b) + ',' + w;
    if (seen.has(key)) return 'Edges joining the same two nodes need different weights.';
    seen.add(key);
  }
  return null;
}

