function minMaxWeight(n, edges, threshold) {
  const incoming = Array.from({ length: n }, () => []);
  for (const [from, to, weight] of edges) {
    incoming[to].push([from, weight]);
  }
  const allReachZero = (limit) => {
    const seen = new Array(n).fill(false);
    seen[0] = true;
    const queue = [0];
    for (let head = 0; head < queue.length; head++) {
      for (const [from, weight] of incoming[queue[head]]) {
        if (weight <= limit && !seen[from]) {
          seen[from] = true;
          queue.push(from);
        }
      }
    }
    return queue.length === n;
  };
  const weights = [...new Set(edges.map(edge => edge[2]))].sort((a, b) => a - b);
  let left = 0;
  let right = weights.length - 1;
  if (!allReachZero(weights[right])) {
    return -1;
  }
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (allReachZero(weights[mid])) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return weights[left];
}

