function minMaxWeight(n, edges, threshold) {
  // Try every subset of edges; keep those that obey threshold and let every node reach 0, and take the lightest top weight.
  let best = -1;
  for (let mask = 1; mask < 2 ** edges.length; mask++) {
    const kept = edges.filter((_, i) => Math.floor(mask / 2 ** i) % 2 === 1);
    const out = new Array(n).fill(0);
    for (const [a] of kept) out[a]++;
    if (out.some(count => count > threshold)) continue;
    const reaches = new Array(n).fill(false);
    reaches[0] = true;
    for (let changed = true; changed; ) {
      changed = false;
      for (const [a, b] of kept) if (reaches[b] && !reaches[a]) { reaches[a] = true; changed = true; }
    }
    if (!reaches.every(Boolean)) continue;
    const top = Math.max(...kept.map(edge => edge[2]));
    if (best === -1 || top < best) best = top;
  }
  return best;
}

