function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 800 + pick(400) : 2 + pick(5);
  const limit = size === 'large' ? 2000 : Math.min(10, n * (n - 1) / 2);
  const top = size === 'large' ? [1000, 1000000][pick(2)] : [3, 6, 1000000][pick(3)];
  const edges = [];
  const used = new Set();
  // Edges joining the same two nodes need different weights.
  const add = (a, b) => {
    const weight = 1 + pick(top), key = Math.min(a, b) + ',' + Math.max(a, b) + ',' + weight;
    if (!used.has(key)) { used.add(key); edges.push([a, b, weight]); }
  };
  // Usually give every node a path to 0 first (a random tree pointing at 0), so the answer is not always -1.
  if (size === 'large' || rand() < 0.6) {
    const order = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 1; i--) { const j = 1 + pick(i); [order[i], order[j]] = [order[j], order[i]]; }
    for (let i = 1; i < n; i++) while (edges.length < i) add(order[i], order[pick(i)]);
  }
  const target = size === 'large' ? limit : Math.max(edges.length, 1 + pick(limit));
  while (edges.length < target) {
    const a = pick(n);
    let b = pick(n - 1);
    if (b >= a) b++;
    add(a, b);
  }
  return [n, edges, 1 + pick(n - 1)];
}
